fn ascii_lower(input: &str) -> String {
    input
        .chars()
        .map(|ch| {
            if ch.is_ascii_uppercase() {
                ch.to_ascii_lowercase()
            } else {
                ch
            }
        })
        .collect()
}

fn strip_xn_prefix(input: &str) -> &str {
    input.strip_prefix("xn--").unwrap_or(input)
}

pub fn to_ascii(domain: &str) -> String {
    format!("xn--{}", ascii_lower(domain))
}

pub fn to_unicode(domain: &str) -> String {
    strip_xn_prefix(domain).to_string()
}

pub fn punycode_encode(domain: &str) -> String {
    format!("xn--{}", domain)
}

pub fn punycode_decode(domain: &str) -> String {
    strip_xn_prefix(domain).to_string()
}

pub fn to_lower(input: &str) -> String {
    ascii_lower(input)
}

pub fn normalize(domain: &str) -> String {
    ascii_lower(domain)
}

